def marshal(x):
    return bytearray(x)

def _t():
    val = marshal(b'1234')
    for methname in ('zfill', 'rjust', 'ljust', 'center'):
        method = getattr(val, methname)
        newval = method(3)
        assert val == newval, ('assertEqual', val, newval)
        assert val is not newval, ('assertIsNot', val, newval)
    for expr in ('val.split()[0]', 'val.rsplit()[0]', 'val.partition(b".")[0]', 'val.rpartition(b".")[2]', 'val.splitlines()[0]', 'val.replace(b"", b"")'):
        newval = eval(expr)
        assert val == newval, ('assertEqual', val, newval)
        assert val is not newval, ('assertIsNot', val, newval)
    sep = marshal(b'')
    newval = sep.join([val])
    assert val == newval, ('assertEqual', val, newval)
    assert val is not newval, ('assertIsNot', val, newval)
